  "inlineSchema": "// Lunar Studio — Client Management Tool\n// Models are introduced phase by phase (PHASE_3 onward).\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── PHASE_3 — Team Members & Roles (RBAC) ───\n\nenum RoleName {\n  ADMIN\n  CLIENT_MANAGER\n  BUSINESS_ANALYST\n  SALES\n  FINANCE\n  DEVELOPER\n  PROJECT_MANAGER\n}\n\nenum MemberStatus {\n  ACTIVE\n  INACTIVE\n  PENDING\n}\n\n/// Domain profile for a person using the tool. Linked to a Neon Auth\n/// (neon_auth.user) identity via `authUserId` — a plain string, no cross-schema\n/// FK. Set at provisioning (auth.admin.createUser); null only for the manually\n/// inserted bootstrap admin until first sign-in. `roles` is an enum array — a\n/// member's roles live in one row. Members are never hard-deleted; they go INACTIVE.\nmodel TeamMember {\n  id         String       @id @default(cuid())\n  authUserId String?      @unique\n  name       String\n  email      String       @unique\n  phone      String?\n  image      String?\n  roles      RoleName[]\n  status     MemberStatus @default(ACTIVE)\n  createdAt  DateTime     @default(now())\n  updatedAt  DateTime     @updatedAt\n\n  @@map(\"team_member\")\n}\n\n// ─── PHASE_4 — Businesses, Contacts & Activity Log ───\n\nenum ContactRole {\n  OWNER\n  MANAGER\n  CTO\n  OTHER\n}\n\n/// Permanent client identity. Never hard-deleted (universal rule #1). Editing\n/// business info must not mutate historical pipeline snapshots (added PHASE_5).\nmodel Business {\n  id          String     @id @default(cuid())\n  name        String\n  website     String?\n  email       String?\n  phone       String?\n  industry    String?\n  location    String?\n  address     String?\n  social      Json? // { linkedin, instagram, facebook, x }\n  metrics     Json? // business research / metrics (PHASE_7 also writes here)\n  notes       String?\n  contacts    Contact[]\n  pipelines   Pipeline[]\n  createdById String?\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  @@index([name])\n  @@index([email])\n  @@map(\"business\")\n}\n\n/// A person at a Business. Exactly one Contact per business is Primary; the\n/// invariant is enforced in a transaction (unset previous primary on change).\nmodel Contact {\n  id         String      @id @default(cuid())\n  businessId String\n  business   Business    @relation(fields: [businessId], references: [id])\n  name       String\n  email      String\n  phone      String?\n  role       ContactRole @default(OTHER)\n  isPrimary  Boolean     @default(false)\n  notes      String?\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n\n  @@index([businessId])\n  @@map(\"contact\")\n}\n\n/// Cross-cutting audit trail. Written by every mutating action from PHASE_4 on.\n/// actorId/businessId/pipelineId are denormalized (no FK) for fast timelines.\nmodel ActivityLog {\n  id         String   @id @default(cuid())\n  actorId    String?\n  action     String\n  entityType String\n  entityId   String\n  businessId String?\n  pipelineId String?\n  metadata   Json?\n  createdAt  DateTime @default(now())\n\n  @@index([businessId, createdAt])\n  @@index([entityType, entityId])\n  @@map(\"activity_log\")\n}\n\n// ─── PHASE_5 — Pipelines & Phase State Machine ───\n\nenum PhaseType {\n  CONTACT_INFO\n  DISCOVERY\n  BUSINESS_UNDERSTANDING\n  REQUIREMENT\n  QUOTATION\n  PROJECT_MANAGEMENT\n}\n\nenum PhaseStatus {\n  ACTIVE\n  PROMOTED\n  DEACTIVATED\n}\n\nenum PipelineStatus {\n  ACTIVE\n  DEACTIVATED\n  COMPLETED\n}\n\nenum LeadSource {\n  WEBSITE\n  INSTAGRAM\n  LINKEDIN\n  REFERRAL\n  DIRECT\n  COLD\n  MANUAL_RESEARCH\n  OTHER\n}\n\n/// One opportunity for a Business. Moves forward-only through the fixed phase\n/// order via the state machine (promote / deactivate). Never hard-deleted.\n/// ownerId / deactivatedById / deactivationReasonId are denormalized ids (no FK).\nmodel Pipeline {\n  id                   String          @id @default(cuid())\n  code                 String          @unique // PL-00123\n  businessId           String\n  business             Business        @relation(fields: [businessId], references: [id])\n  name                 String\n  opportunityType      String?\n  leadSource           LeadSource      @default(OTHER)\n  ownerId              String?\n  notes                String?\n  currentPhase         PhaseType       @default(DISCOVERY)\n  status               PipelineStatus  @default(ACTIVE)\n  phases               PipelinePhase[]\n  deactivationReasonId String?\n  deactivatedAt        DateTime?\n  deactivatedById      String?\n  createdAt            DateTime        @default(now())\n  updatedAt            DateTime        @updatedAt\n\n  @@index([businessId])\n  @@index([status])\n  @@index([currentPhase])\n  @@map(\"pipeline\")\n}\n\n/// A single phase instance on a pipeline. Exactly one row per (pipeline, type).\n/// Phase-specific payload tables attach in PHASE_7.\nmodel PipelinePhase {\n  id           String      @id @default(cuid())\n  pipelineId   String\n  pipeline     Pipeline    @relation(fields: [pipelineId], references: [id])\n  type         PhaseType\n  status       PhaseStatus @default(ACTIVE)\n  ownerId      String?\n  startedAt    DateTime    @default(now())\n  promotedAt   DateTime?\n  promotedById String?\n  promoteNotes String?\n  notes        String?\n\n  @@unique([pipelineId, type])\n  @@index([pipelineId])\n  @@map(\"pipeline_phase\")\n}\n\n/// Seeded lookup of reasons a pipeline can be deactivated (WF-19). usageCount is\n/// maintained for the reasons report (WF-55).\nmodel DeactivationReason {\n  id         String  @id @default(cuid())\n  label      String  @unique\n  enabled    Boolean @default(true)\n  usageCount Int     @default(0)\n\n  @@map(\"deactivation_reason\")\n}\n\n// ─── PHASE_6 — Tasks, Follow-ups & Resources ───\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nenum ResourceType {\n  PDF\n  DOCX\n  IMAGE\n  TEXT\n  QUOTATION\n  REQUIREMENT\n  RESEARCH\n  MEETING_NOTES\n  OTHER\n}\n\n/// Independent work item, optionally linked to a Business/Pipeline/Phase.\n/// \"Overdue\" is derived in reads (status not COMPLETED/CANCELLED and dueAt < now),\n/// never stored. assignee/business/pipeline ids are denormalized (no FK).\nmodel Task {\n  id          String     @id @default(cuid())\n  title       String\n  assigneeId  String?\n  createdById String?\n  dueAt       DateTime?\n  priority    Priority   @default(MEDIUM)\n  status      TaskStatus @default(TODO)\n  businessId  String?\n  pipelineId  String?\n  phaseType   PhaseType?\n  notes       String?\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  @@index([assigneeId, dueAt])\n  @@index([status])\n  @@index([pipelineId])\n  @@map(\"task\")\n}\n\n/// Scheduled future action (used heavily for unresponsive / revisit-later cases).\n/// History is preserved — follow-ups are never bulk-deleted.\nmodel FollowUp {\n  id          String     @id @default(cuid())\n  businessId  String?\n  pipelineId  String?\n  phaseType   PhaseType?\n  reason      String\n  dueAt       DateTime\n  assigneeId  String?\n  notes       String?\n  completedAt DateTime?\n  createdById String?\n  createdAt   DateTime   @default(now())\n\n  @@index([assigneeId, dueAt])\n  @@index([pipelineId])\n  @@map(\"follow_up\")\n}\n\n/// File/document metadata; the object itself lives in Cloudflare R2 (objectKey).\n/// Scoped to a Business, or Business + Pipeline + Phase.\nmodel Resource {\n  id          String       @id @default(cuid())\n  name        String\n  type        ResourceType @default(OTHER)\n  objectKey   String\n  sizeBytes   Int?\n  contentType String?\n  businessId  String?\n  pipelineId  String?\n  phaseType   PhaseType?\n  description String?\n  createdById String?\n  createdAt   DateTime     @default(now())\n\n  @@index([businessId])\n  @@index([pipelineId])\n  @@index([type])\n  @@map(\"resource\")\n}\n",
